class AreaCalculator:
    def __init__(self) -> None:
        self.shapes = []

    def add_shape(self, shape):
        self.shapes.append(shape)

    def sum(self):
        areas = [math.pow(shape.length, 2) if isinstance(shape, Square) else math.pi * math.pow(shape.radius, 2) for shape in self.shapes]
        return sum(areas)

class ShapeSerializer:
    def __init__(self, areaCalculator: AreaCalculator) -> None:
        self.calculator = areaCalculator

    def to_json(self):
        return json.dumps({'sum': self.calculator.sum()})

    def to_html(self):
        return f'Sum of the areas of provided shapes: {self.calculator.sum()}'
